local config = {
  ui_story_32110401_1_dialog_content = "Tengo buenas noticias para contarte.",
  ui_story_32110401_2_dialog_content = "He estado siguiendo un régimen de entrenamiento especial para mejorar la precisión de mis ataques.",
  ui_story_32110401_3_dialog_content = "¡Y ahora finalmente estoy empezando a ver resultados!",
  ui_story_32110401_4_dialog_content = "Sabes, incluso la increíble señorita Vice me elogió por lo lejos que he llegado!",
  ui_story_32110401_5_dialog_content = "<anim type=Shake>B-B-Bullseye, Z-Zarya... Mira... T-Tú lo hiciste...</anim>",
  ui_story_32110401_6_dialog_content = "<anim type=Shake>C-C-Claramente esto significa... q-q-que la p-p-precisión... ya no es un p-p-problema para ti... más...</anim>",
  ui_story_32110401_7_dialog_content = "¿En serio? No sentí realmente como si hubiera acertado al objetivo...",
