  ui_story_32110401_9_dialog_content = "<anim type=Shake>Genial... Esperemos que esto signifique que habrá muchos menos muebles en el Colossus que necesiten ser descongelados... por alguna extraña razón...</anim>",
  ui_story_32110401_10_dialog_content = "<size=50><anim type=Shake>¡Achu!</anim></size>",
  ui_story_32110401_11_dialog_content = "\"La increíble señorita Vice...\"",
  ui_story_32110401_12_dialog_content = "Zarya, parece que pones a todas las hermanas mayores confiables que conoces en un pedestal...",
  ui_story_32110401_13_dialog_content = "No hay nadie más por aquí en este momento.",
  ui_story_32110401_14_dialog_content = "¿Te gustaría aprovechar esta oportunidad para ver los resultados de mi entrenamiento con la señorita Vice?",
  ui_story_32110401_15_dialog_content = "Seguro.",
  ui_story_32110401_16_dialog_content = "Acabo de tomar una taza caliente de café y estoy listo para salir. Si crees que puedes congelarme, ¡adelante!",
  ui_story_32110401_17_dialog_content = "Uh... Parece que no crees que haya mejorado en absoluto.",
  ui_story_32110401_18_dialog_content = "Teniendo en cuenta lo duro que la señorita Vice ha estado trabajando para entrenarme, ¡simplemente TENGO que impresionarte!",
  ui_story_32110401_19_dialog_content = "<color=#e8d9bb>Un minuto después...</color>",
  ui_story_32110401_20_dialog_content = "Primero... concentrar mi mente.",
  ui_story_32110401_21_dialog_content = "Entonces... reúne la Lumina y controla el poder, como si moviera mi meñique.",
  ui_story_32110401_22_dialog_content = "Finalmente... ¡aprovecha el momento adecuado! ¡Concentra el poder en un solo flujo y desátalo!",
