  ui_story_32110401_24_dialog_content = "¿Ah?",
  ui_story_32110401_25_dialog_content = "Estaba apuntando específicamente a la cinta atada a esa silla...",
  ui_story_32110401_26_dialog_content = "¿Por qué está toda la habitación congelada?!",
  ui_story_32110401_27_dialog_content = "Tal vez simplemente no te sientes al cien por ciento en este momento. ¿Qué tal si lo intentamos de nuevo otro día...?",
  ui_story_32110401_28_dialog_content = "¡No! La señorita Vice dice que el control perfecto se logra a través de la práctica rigurosa. ¡No pondré excusas para mí mismo!",
  ui_story_32110401_29_dialog_content = "Eso fue simplemente un accidente hace un momento. ¡Probemos de nuevo en otro lugar!",
  ui_story_32110401_30_dialog_content = "¡Usaré esa lata de café como mi objetivo esta vez! ¡Definitivamente la golpearé!",
  ui_story_32110401_31_dialog_content = "Espera un minuto—",
  ui_story_32110401_32_dialog_content = "<size=45>¡No ese! ¡Eso no es un café común!</size>",
  ui_story_32110401_33_dialog_content = "¡Hola!",
  ui_story_32110401_34_dialog_content = "<size=45>¡Aaaaaah—!</size>",
  ui_story_32110401_35_dialog_content = "¡Esos son los granos de café súper caros que le pedí a la Srta. Sheol que consiguiera para mí!",
  ui_story_32110401_36_dialog_content = "Ni siquiera he tenido la oportunidad de probarlos todavía... y ahora están todos... congelados...",
  ui_story_32110401_37_dialog_content = "¡Ah... L-Lo siento!",
  ui_story_32110401_38_dialog_content = "Suspiro... Todo ese esfuerzo, todo el trabajo duro que he puesto en estos últimos días... todo fue en vano.",
  ui_story_32110401_39_option_content = "(Da una sugerencia específica a Zarya)",
  ui_story_32110401_40_dialog_content = "Tengo una sugerencia.",
  ui_story_32110401_41_dialog_content = "Antes de trabajar en tu precisión, intenta reducir la intensidad de la Lumina que estás liberando.",
  ui_story_32110401_42_dialog_content = "Eso definitivamente hará que sea más fácil de controlar.",
  ui_story_32110401_43_option_content = "(Dile a Zarya que beba más agua caliente)",
  ui_story_32110401_44_dialog_content = "Olvida todo eso por ahora, solo bebe más agua caliente y caliéntate un poco primero.",
  ui_story_32110401_45_dialog_content = "No quiero... Tú bebe algo...",
  ui_story_32110401_46_dialog_content = "No dejes que te afecte. Dejemos la puntería precisa a un lado por ahora.",
  ui_story_32110401_47_dialog_content = "Quizás si comienzas reduciendo la potencia de tu Lumina, ¿tu lanzamiento podría resultar más fluido?",
  ui_story_32110401_48_dialog_content = "¿Ah?",
  ui_story_32110401_49_dialog_content = "No puedo hacer promesas. Después de todo, ni siquiera soy un auroriano.",
  ui_story_32110401_50_dialog_content = "Solo estoy pensando, basándome en mi habilidad como Celestita, parece que estás ejerciendo demasiado poder.",
  ui_story_32110401_51_dialog_content = "Tiene sentido que puedas controlar mejor tu poder si intentas lanzar menos de él a la vez.",
  ui_story_32110401_52_dialog_content = "Una vez que domines este primer paso, puedes aumentar gradualmente tu poder hasta que puedas controlarlo por completo.",
  ui_story_32110401_53_dialog_content = "Esa ciertamente es una solución viable.",
  ui_story_32110401_54_dialog_content = "Pero eso solo podría ser demasiado simple para ti.",
  ui_story_32110401_55_dialog_content = "¿Mmm?",
  ui_story_32110401_56_dialog_content = "Me pregunto si hay botellas o latas baratas por aquí...",
  ui_story_32110401_57_dialog_content = "Ah, encontré uno. Esto debería hacer el truco.",
  ui_story_32110401_58_dialog_content = "¿Por qué te pones esa botella en la cabeza?",
  ui_story_32110401_59_dialog_content = "¿No quieres decir...?!",
  ui_story_32110401_60_dialog_content = "Zarya, quiero que golpees la botella en mi cabeza con tu hielo.",
  ui_story_32110401_61_dialog_content = "¿Eh? ¡Eso suena increíblemente peligroso!",
  ui_story_32110401_62_dialog_content = "Si te golpeara por error, tú...!",
  ui_story_32110401_63_dialog_content = "¿Por qué asumes que fracasarás incluso antes de intentarlo?",
  ui_story_32110401_64_dialog_content = "No te preocupes. No es como si no me hubieran golpeado tus Luminatics antes. Debe ser que ya he desarrollado cierta resistencia a ellas.",
  ui_story_32110401_65_dialog_content = "Pero...",
  ui_story_32110401_66_dialog_content = "Relájate, Vice y yo ya hemos hecho esto antes.",
  ui_story_32110401_67_dialog_content = "Si realmente estás tan preocupado, simplemente usa la mínima cantidad de poder que puedas reunir para golpear la botella.",
  ui_story_32110401_68_dialog_content = "Tengo la sensación de que te resulta difícil controlar tu poder, ¿verdad? Bueno, tal vez sea porque siempre practicas con objetos inanimados.",
  ui_story_32110401_69_dialog_content = "Además, asegúrate de practicar tus habilidades en lugares donde no haya nadie alrededor.",
  ui_story_32110401_70_dialog_content = "Entonces, aunque cometas errores, no tienes que preocuparte por lastimar a nadie.",
  ui_story_32110401_71_dialog_content = "Correcto... pero, ¿qué está mal con eso?",
  ui_story_32110401_72_dialog_content = "¿No has considerado que, como siempre estás entrenando en áreas vacías, contra objetivos sin vida...",
  ui_story_32110401_73_dialog_content = "Básicamente nunca has tenido que enfocar tu poder antes.",
  ui_story_32110401_74_dialog_content = "(!!!)",
  ui_story_32110401_75_dialog_content = "Esta vez, tienes que golpear la botella en mi cabeza...",
  ui_story_32110401_76_dialog_content = "Si no quieres que me lastime, eso es.",
  ui_story_32110401_77_dialog_content = "PlayerName... eso en realidad tiene mucho sentido.",
  ui_story_32110401_78_dialog_content = "¡No puedo volver atrás ahora!",
  ui_story_32110401_79_dialog_content = "(No puedo cometer errores esta vez... No puedo permitirme equivocarme...)",
  ui_story_32110401_80_dialog_content = "(Tal como dijo la señorita Vice, bloquea todos los pensamientos innecesarios...)",
  ui_story_32110401_81_dialog_content = "(Solo fusionando tu conciencia con los cristales de hielo podrás tener éxito...)",
  ui_story_32110401_82_dialog_content = "Y recuerda: usa la cantidad mínima de energía...",
  ui_story_32110401_83_dialog_content = "¡Vamos a darle color a la nieve!",
  ui_story_32110401_84_dialog_content = "¡¿Lo hice?!",
  ui_story_32110401_85_dialog_content = "Uf... Eso es lo que pensaba.",
  ui_story_32110401_86_dialog_content = "Zarya, no es que no seas bueno con la precisión, es que simplemente eres demasiado bueno desatando tu poder.",
  ui_story_32110401_87_dialog_content = "¿Qué significa eso?",
  ui_story_32110401_88_dialog_content = "Significa que no deberías preocuparte por hacer todo lo posible para controlar tu precisión como lo hacen todos los demás...",
  ui_story_32110401_89_dialog_content = "Pero sí necesitas reducir tu poder.",
  ui_story_32110401_90_dialog_content = "Es como verter café: es naturalmente más fácil servir demasiado café cuando tu lata tiene una abertura ancha.",
  ui_story_32110401_91_dialog_content = "... ¿Mi poder... tiene una gran apertura?",
  ui_story_32110401_92_dialog_content = "Así es. Por lo tanto, te aconsejo que utilices métodos de combate más rápidos y flexibles cuando estés en batalla.",
  ui_story_32110401_93_dialog_content = "Esto debería reducir considerablemente tus posibilidades de cometer un error.",
  ui_story_32110401_94_dialog_content = "Mmm... ¡Entendido! La próxima vez, lo tendré en mente e intentaré hacer lo mismo de nuevo.",
  ui_story_32110401_95_dialog_content = "Vaya, y ni siquiera me respondiste... Parece que no solo tu habilidad ha crecido hoy, tu personalidad también parece haber subido de nivel...",
  ui_story_32110401_96_dialog_content = "¿Qué estás diciendo, PlayerName?",
  ui_story_32110401_97_dialog_content = "¿Quieres decir... que he crecido de otra manera, además de mejorar mis Luminatics?",
  ui_story_32110401_98_dialog_content = "Ehm, sí... ¿Qué pasa?",
  ui_story_32110401_99_dialog_content = "Entonces, ¿crees que soy más o menos una dama madura ahora, es así?",
  ui_story_32110401_100_dialog_content = "¿Eh? ¿Por qué dirías eso...? No, no lo creo...",
  ui_story_32110401_101_dialog_content = "¡Ay! ¡¿Qué planeas hacer?!",
  ui_story_32110401_102_dialog_content = "... Mi querido PlayerName...",
  ui_story_32110401_103_dialog_content = "¿Podrías seguir siendo mi compañero de entrenamiento a partir de ahora?",
  ui_story_32110401_104_dialog_content = "Después de todo, cuando te tengo como blanco para practicar, es cuando mi mente está más concentrada...",
  ui_story_32110401_105_dialog_content = "¡Por favooooor!",
  ui_story_32110401_106_dialog_content = "... ¡Necesito pensarlo!",
  ui_story_32110601_1_dialog_content = "(Cuando era niño, a menudo me dejaban solo en casa.)",
  ui_story_32110601_2_dialog_content = "(Mi hermana tenía que salir a patrullar y no podía estar conmigo todo el tiempo. Los otros niños tampoco jugaban conmigo.)",
  ui_story_32110601_3_dialog_content = "(Había solo unas pocas cosas en la vida que me hacían sonreír en ese entonces, y la mayoría de ellas estaban en el libro de cuentos que mi hermana me dio.)",
  ui_story_32110601_4_dialog_content = "(El libro hablaba del hielo de Northland, de cómo se volvía sólido y fuerte, pero se convertía en agua de mar cálida al exponerse al mundo exterior.)",
  ui_story_32110601_5_dialog_content = "(Mi hermana también solía decirme que podríamos ponernos nuestros trajes de baño y visitar esa fascinante tierra de misterio algún día.)",
  ui_story_32110601_6_dialog_content = "(Pero...)",
  ui_story_32110601_7_dialog_content = "<color=#e8d9bb>Salpicando—</color>",
  ui_story_32110601_8_dialog_content = "Zarya¿?",
  ui_story_32110601_9_dialog_content = "<size=45>Zarya¿?</size>",
  ui_story_32110601_10_dialog_content = "Oh...",
  ui_story_32110601_11_dialog_content = "¿Qué pasa? ¿Es este el lugar equivocado?",
  ui_story_32110601_12_dialog_content = "¿No es este el océano de aquel libro?",
  ui_story_32110601_13_dialog_content = "Eso no es lo que está mal, PlayerName.",
  ui_story_32110601_14_dialog_content = "Es solo que... esta es la primera vez que veo un océano sin hielo sólido con mis propios ojos. Es... asombroso.",
  ui_story_32110601_15_dialog_content = "Es tan hermoso...",
  ui_story_32110601_16_dialog_content = "El mundo exterior es enorme... Esto es solo una pequeña parte de él.",
  ui_story_32110601_17_dialog_content = "Prueba meter los pies en el agua. No hay nada que se le parezca.",
  ui_story_32110601_18_dialog_content = "Oh, ¿así?",
  ui_story_32110601_19_dialog_content = "Oh—",
  ui_story_32110601_20_dialog_content = "¿Qué opinas? Se siente bien, ¿verdad?",
  ui_story_32110601_21_dialog_content = "No es exactamente igual a las aguas termales de Northland, pero sigue siendo muy agradable... Es tan cálido.",
  ui_story_32110601_22_dialog_content = "Solía bañarme en las aguas termales en Northland...",
  ui_story_32110601_23_dialog_content = "Los vientos en Northland son tan fríos y cortantes. Mi hermana se negaría a salir del acogedor manantial caliente.",
  ui_story_32110601_24_dialog_content = "Pero aquí es diferente. El viento es tan suave.",
  ui_story_32110601_25_dialog_content = "Incluso si nadara bajo la brisa del océano, no sentiría ese frío penetrante.",
  ui_story_32110601_26_dialog_content = "Si tan solo ella...",
  ui_story_32110601_27_dialog_content = "<color=#e8d9bb>Golpeteo de pitter—</color>",
  ui_story_32110601_28_dialog_content = "¿Eh? ¡Acaba de empezar a llover de repente!",
  ui_story_32110601_29_dialog_content = "Incluso después de pedir prestadas todas estas muñecas soleadas a Hiiro y los demás...",
  ui_story_32110601_30_dialog_content = "¿No eran suficientes cincuenta de ellos?!",
  ui_story_32110601_31_dialog_content = "Tal vez... ¿deberíamos dejarlo por hoy?",
  ui_story_32110601_32_dialog_content = "¿Qué estás mirando?",
  ui_story_32110601_33_dialog_content = "Esta lluvia...",
  ui_story_32110601_34_dialog_content = "El agua de lluvia aquí... Es tan ligera y no se congela...",
  ui_story_32110601_35_dialog_content = "Si sigues así, te resfriarás.",
  ui_story_32110601_36_dialog_content = "Y la ropa nueva que llevas hoy se va a mojar toda.",
  ui_story_32110601_37_dialog_content = "No me enfermaré con una lluvia cálida como esta.",
  ui_story_32110601_38_dialog_content = "Comparado con el gélido ataúd en el que estuve prisionero durante cien años, esta lluvia es como una caricia suave de la naturaleza.",
  ui_story_32110601_39_dialog_content = "Esto es lo que imagino que se sentiría al tener las hadas de mi libro de cuentos revoloteando con sus alas sobre mi rostro.",
  ui_story_32110601_40_dialog_content = "Oye, ¿y ahora simplemente te sientas?",
  ui_story_32110601_41_dialog_content = "Vaya puñado...",
  ui_story_32110601_42_dialog_content = "<color=#e8d9bb>La lluvia cae con golpeteo suave...</color>",
  ui_story_32110601_43_dialog_content = "<color=#e8d9bb>Zarya se sienta en las rocas, su ropa empapada por la lluvia fría.</color>",
  ui_story_32110601_44_dialog_content = "¿Mmm?",
  ui_story_32110601_45_dialog_content = "Uf, menos mal que traje un paraguas...",
  ui_story_32110601_46_dialog_content = "PlayerName, realmente no necesitas preocuparte por mí.",
  ui_story_32110601_47_dialog_content = "¡No estoy preocupado! Es solo que...",
  ui_story_32110601_48_dialog_content = "... Uh, si te resfrías, No. 33 me culpará por no cuidarte bien!",
  ui_story_32110601_49_dialog_content = "No—",
  ui_story_32110601_50_dialog_content = "Entonces eso es todo, ¿eh? Realmente no es honesto de tu parte...",
  ui_story_32110601_51_dialog_content = "¡Solo muévelo! No pienses ni por un segundo que soy tan imprudente como tú...",
  ui_story_32110601_52_dialog_content = "Solo tengo la sensación de que algo te está preocupando.",
  ui_story_32110601_53_dialog_content = "Te has sentido un poco raro desde que viste el océano.",
  ui_story_32110601_54_dialog_content = "¿Te gustaría decirme qué te molesta?",
  ui_story_32110601_55_dialog_content = "Como sabes, el clima en Northland es duro, por decir lo menos.",
  ui_story_32110601_56_dialog_content = "Cuando estaba creciendo, un clima sombrío como este era una señal de que pronto caería granizo.",
  ui_story_32110601_57_dialog_content = "Mi hermana se apresuraría a volver a casa para evitar el granizo, e incluso mi padre pondría una pausa temporal en sus asuntos de negocios.",
  ui_story_32110601_58_dialog_content = "Todo eso fue hace tanto tiempo, pero aún recuerdo el aterrador sonido del granizo cayendo.",
  ui_story_32110601_59_dialog_content = "Siempre que tenía miedo, mi hermana sacaba un libro de cuentos y me consolaba con historias del mundo exterior.",
  ui_story_32110601_60_dialog_content = "Ella acariciaría mi cabeza y susurraría suavemente en mi oído:",
  ui_story_32110601_61_dialog_content = "\"Zarya, sabes que no hay necesidad de tener miedo a la lluvia y la nieve, ¿verdad? Hay un mundo increíble esperándote allá afuera.\"",
  ui_story_32110601_62_dialog_content = "\"Hay lugares donde el mar no se congela y la lluvia es suave y reconfortante.\"",
  ui_story_32110601_63_dialog_content = "\"Si tenemos la oportunidad, usemos nuestros trajes de baño y nademos en un hermoso paraíso exótico algún día.\"",
  ui_story_32110601_64_dialog_content = "Y ahora...",
  ui_story_32110601_65_dialog_content = "Aquí estoy.",
  ui_story_32110601_66_dialog_content = "Donde el mar nunca se congela... usando mi traje de baño...",
  ui_story_32110601_67_dialog_content = "Pero no hay nadie aquí para celebrar conmigo que este sueño se haya hecho realidad.",
  ui_story_32110601_68_dialog_content = "¿A todos en tu familia les interesaba tanto el mundo exterior como a ti?",
  ui_story_32110601_69_dialog_content = "Creo... que sí lo eran.",
  ui_story_32110601_70_dialog_content = "Mi hermana, por supuesto, siempre quiso mostrarme el mundo exterior, pero su trabajo siempre se interponía.",
  ui_story_32110601_71_dialog_content = "A mi papá también le intrigaban los productos extranjeros.",
  ui_story_32110601_72_dialog_content = "En cuanto a mi mamá... ella murió cuando yo era joven, así que apenas puedo recordarla ahora.",
  ui_story_32110601_73_dialog_content = "Pero siempre se aferraba a mi padre, que viajaba a menudo y lejos, así que supongo que probablemente tendría curiosidad por el mundo más amplio.",
  ui_story_32110601_74_dialog_content = "Entonces, ¿no has cumplido ya con tu acuerdo con todos ellos?",
  ui_story_32110601_75_dialog_content = "¿Mmm?",
  ui_story_32110601_76_dialog_content = "Después de que dejaste Northland, en lugar de encerrarte en tu habitación, decidiste caminar afuera.",
  ui_story_32110601_77_dialog_content = "Saliste a ver el mundo que los llenaba de tanta curiosidad y ansias de viajar.",
  ui_story_32110601_78_dialog_content = "Aprecia el presente y el cielo siempre estará despejado.",
  ui_story_32110601_79_dialog_content = "Je, ¿esa es tu lengua de plata trabajando de nuevo...? Realmente tienes el don de la palabrería.",
  ui_story_32110601_80_dialog_content = "Desafortunadamente, parece que el clima no mejorará hoy, sin importar cuán elocuente puedas ser.",
  ui_story_32110601_81_dialog_content = "<color=#e8d9bb>Una suave brisa sopla, haciendo que las nubes inquietas se disipen tan rápido como se formaron.</color>",
  ui_story_32110601_82_dialog_content = "<color=#e8d9bb>Rayos de sol atraviesan las nubes opresivas y se proyectan sobre la playa.</color>",
  ui_story_32110601_83_dialog_content = "¡Ajá! Parece que la lluvia realmente empieza y se detiene cuando tú lo dices...",
  ui_story_32110601_84_dialog_content = "Hmm, supongo que estaba equivocado... ¿Es posible que puedas controlar el clima con Luminatics?",
  ui_story_32110601_85_dialog_content = "Caelestites no pueden usar Lumina.",
  ui_story_32110601_86_dialog_content = "Si te pareció divertida la lluvia, ¡caminar por la playa te va a encantar! Aún no lo has intentado, ¿verdad?",
  ui_story_32110601_87_dialog_content = "no he...",
  ui_story_32110601_88_dialog_content = "Bueno, en ese caso, vamos.",
  ui_story_32110601_89_option_content = "Toma la mano de Zarya",
  ui_story_32110601_90_dialog_content = "La brisa marina soplando a través del cielo azul claro después de la lluvia es tan suave...",
  ui_story_32110601_91_dialog_content = "El sonido de mis zapatos raspando en la playa... Me gusta este sonido.",
  ui_story_32110601_92_dialog_content = "¿Mi hermana y los demás también experimentaron esta misma escena?",
  ui_story_32110601_93_dialog_content = "Han pasado cien años desde que hicimos esa promesa.",
  ui_story_32110601_94_dialog_content = "¿Es posible que hayan venido a esta playa antes?",
  ui_story_32110601_95_option_content = "Sí, muy probable.",
  ui_story_32110601_96_dialog_content = "Creo que deben haber venido a esta playa.",
  ui_story_32110601_97_dialog_content = "Deben haber experimentado también la suave brisa marina después de la lluvia y respirado este fresco aire del océano.",
  ui_story_32110601_98_dialog_content = "Probablemente también visitaron muchos otros lugares.",
  ui_story_32110601_99_dialog_content = "Camina en sus pasos y presencia el mundo exterior que alguna vez exploraron.",
  ui_story_32110601_100_dialog_content = "Además, a ti también te gusta bastante el mundo exterior.",
  ui_story_32110601_101_dialog_content = "Sí, me gusta.",
  ui_story_32110601_102_option_content = "Es posible que no hayan estado aquí antes.",
  ui_story_32110601_103_dialog_content = "¿Nunca vinieron aquí...?",
  ui_story_32110601_104_dialog_content = "Pero precisamente porque ellos no vinieron aquí, tú necesitas experimentar el mundo exterior en su lugar.",
  ui_story_32110601_105_dialog_content = "Has visto en qué estaban interesados y lograron el tipo de vida que querían. Eso acerca más sus corazones.",
